function frame(now){const dt=lastFrame?Math.min(.1,(now-lastFrame)/1000):0;lastFrame=now;if(mode==='browser'&&state.mission){const before=state.containers.find(c=>c.id===state.mission.container)?.state;if(tick(state,dt,speed)){persist();renderUI();}else if(before!==state.containers.find(c=>c.id===state.mission?.container)?.state)renderUI();}if(now-lastPaint>30){draw();lastPaint=now;$('missionProgress').textContent=state.mission?`${state.mission.id} · ${Math.round(state.mission.progress*100)} %`:'Simulation prête';}requestAnimationFrame(frame);}renderUI();requestAnimationFrame(frame);
if(['localhost','127.0.0.1'].includes(location.hostname))connect(location.origin).catch(()=>toast('API non disponible : démonstration du navigateur active.'));
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_portique_state',description:'Lire les positions et la configuration de la scène visible.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,state:structuredClone(state)})});document.modelContext.registerTool({name:'start_simulated_transfer',description:'Lancer une mission dans la simulation visible, sans commande matérielle.',inputSchema:{type:'object',properties:{container:{type:'string'},destination:{type:'string'}},required:['container','destination'],additionalProperties:false},execute:async v=>{if(!v||typeof v.container!=='string'||typeof v.destination!=='string')throw Error('Paramètres invalides.');if(!canEdit())throw Error('Simulation non disponible.');if(!destinations(state,v.container).some(d=>d.value===v.destination))throw Error('Destination invalide.');await act('move',{id:v.container,destination:v.destination});return {mission:state.mission};}});}catch{}}

async function loadHardware(){
  $('hardwareTest').disabled=true;
  try{
    const status=await request('/api/hardware/status');
    $('hardwareStatus').textContent=status.telemetry?'Télémétrie disponible pour les essais logiciels. Commandes physiques désactivées.':'Arduino à configurer · aucune mesure reçue · commandes physiques désactivées.';
    $('hardwareTest').disabled=false;
  }catch{
    $('hardwareStatus').textContent='Serveur local indisponible. Lancez demarrer.bat pour accéder aux contrôles logiciels.';
  }
}
$('hardwareRefresh').onclick=loadHardware;
$('hardwareTest').onclick=async()=>{
  $('hardwareTest').disabled=true;
  try{
    const result=await request('/api/hardware/self-test',{});
    $('hardwareResults').textContent=(result.passed?'Tests logiciels réussis. ':'Échec d’un contrôle. ')+result.checks.map(c=>(c.passed?'✓ ':'✗ ')+c.name).join(' · ')+'. Aucun signal envoyé au matériel.';
  }catch(e){$('hardwareResults').textContent='Essai indisponible : '+e.message;}
  finally{$('hardwareTest').disabled=false;}
};

function renderOperation(){
 const op=state.operation&&['running','paused','interrupted'].includes(state.operation.status)?state.operation:retrievalPreview;
 if(!op){$('operationPlan').innerHTML='';return;}
 const active=!!op.id;
 $('operationPlan').innerHTML=`<div class="operation-summary"><strong>${active?'Dégagement en cours':'Plan de dégagement'} · ${esc(op.target)}</strong><p>${op.steps.length} transfert(s) · ${Math.round(op.totalDistanceMm)} mm au total � ${Math.round(op.loadedDistanceMm??op.totalDistanceMm)} mm en charge � ${Math.round(op.emptyDistanceMm??0)} mm � vide${op.estimatedSeconds?' � '+op.estimatedSeconds.toFixed(1)+' s estim�es � 1�':''}. ${op.optimization==='exhaustive'?'Toutes les affectations possibles ont été comparées.':'Meilleur plan trouvé par recherche limitée.'}</p><ol>${op.steps.map((step,i)=>`<li class="${active&&i<op.nextIndex?'done':active&&i===op.nextIndex?'current':''}">${esc(step.container)} → ${esc(step.destination.replace('slot:','Case ').replace('truck:','Camion '))}${step.role==='target'?' · cible':' · dégagement'} <small>${Math.round(step.routeLengthMm)} mm en charge + ${Math.round(step.emptyDistanceMm??0)} mm � vide${step.estimatedSeconds?' � '+step.estimatedSeconds.toFixed(1)+' s':''}</small></li>`).join('')}</ol><p class="tiny">Les conteneurs dégagés restent à leurs nouvelles places. Le coût compare les trajets en charge ; les retours du préhenseur sont à modéliser après le choix mécanique.</p></div>`;
}
async function previewRetrieval(){if(planning)return;
 if(mode!=='server'||!connected)return toast('Le dégagement automatique nécessite le serveur local connecté.');
 planning=true;$('previewBtn').disabled=true;$('moveBtn').disabled=true;$('operationPlan').textContent='Comparaison des emplacements et calcul des trajets…';
 const id=selected,destination=$('destinationSelect').value;
 try{const plan=await request('/api/preview-retrieval',{id,destination});if(id===selected&&destination===$('destinationSelect').value)retrievalPreview=plan;renderUI();}catch(e){$('operationPlan').textContent=e.message;toast(e.message);}finally{planning=false;renderUI();}
}
async function loadHistory(reset=false){
 if(reset){historyRows=[];historyCursor=null;}
 if(mode==='browser'){$('historyList').textContent='Historique PostgreSQL disponible avec le serveur local.';return;}
 try{const rows=await request('/api/history?kind='+encodeURIComponent($('historyFilter').value)+(historyCursor?'&before='+historyCursor:''));historyRows.push(...rows);historyCursor=rows.at(-1)?.id||historyCursor;
 $('historyList').innerHTML=historyRows.map(e=>`<article class="history-entry ${e.kind==='alert'?'alert':''}"><div><time>${esc(new Date(e.at).toLocaleString('fr-FR'))}</time><small>#${e.id} · ${esc(({mission_started:'Transfert lancé',picked:'Prise confirmée',deposited:'Dépôt confirmé',operation_started:'Dégagement lancé',operation_completed:'Dégagement terminé',mission_cancelled:'Annulation',reconciled:'Position confirmée',alert:'Alerte',truck_arrived:'Arrivée camion',truck_departed:'Départ camion',simulation:'Simulation',configuration:'Configuration'})[e.kind]||'Événement')}</small></div><p>${esc(e.message)}</p></article>`).join('')||'Aucun événement pour ce filtre.';$('historyMore').disabled=rows.length<50;
 }catch(e){$('historyList').textContent='Historique indisponible : '+e.message;}
}
$('historyFilter').onchange=()=>loadHistory(true);$('historyMore').onclick=()=>loadHistory(false);
$('checkConfigBtn').onclick=async()=>{try{if(mode!=='server')return $('configImpact').textContent='Le mode navigateur recrée une démonstration. Connectez le serveur pour conserver l’inventaire.';const result=await request('/api/preview-configuration',{config:readConfig()});$('configImpact').textContent=result.possible?`${result.containersPreserved} conteneur(s) conservés. Les coordonnées seront recalculées avec la nouvelle géométrie.`:result.blockers.join(' ');}catch(e){$('configImpact').textContent=e.message;}};
